import subprocess, sys
def run(words, flags=()):
    inp = "\n".join(words)
    p = subprocess.run(["timeout","120","/tmp/orig-srgn","--stdout-detection","force-pipe","-g",*flags],
        input=inp.encode(), capture_output=True)
    out = p.stdout.decode().split("\n")
    if p.stderr: sys.stderr.write("STDERR:"+p.stderr.decode())
    assert len(out)==len(words), (len(out),len(words))
    return list(zip(words,out))
def show(words, flags=()):
    for a,b in run(words,flags):
        print(("  = " if a==b else "  * ")+a+(" -> "+b if a!=b else ""))
if __name__=="__main__":
    words=[l.rstrip("\n") for l in open(sys.argv[1])]
    show(words, sys.argv[2:])
